// rawAPIHelpText renders `api --help`: the command grammar, the body
// sources, the security contract, and this API's generated schemes.
func rawAPIHelpText() string {
	schemes := strings.Join(rawAuthSchemes, ", ")
	if schemes == "" {
		schemes = "none are configured for this API"
	}
	return strings.Join([]string{
		"usage: " + bin + " api METHOD PATH [flags]",
		"",
		"Send one raw request through the SDK transport every typed command",
		"uses: the configured base URL, authentication, retries, timeouts,",
		"request IDs, and the error envelope all apply.",
		"",
		"PATH is relative to the API's base path and begins with a single",
		"slash (for example /accounts/acc_123). Query text, fragments,",
		"absolute URLs, backslashes, control characters, and traversal or",
		"separator escapes are rejected; pass query values with --query.",
		"",
		"Bodies (pick at most one):",
		"  --data '<inline JSON>'  sent as application/json, validated here",
		"  --raw '<literal bytes>' sent as text/plain, exactly as given",
		"  --file <path>           file bytes, sent as application/octet-stream",
		"  --stdin                 stdin to EOF, sent as application/octet-stream",
		"",
		"Query values repeat and keep empty values:",
		"  --query a=1 --query a=2 --query empty=",
		"",
		"Headers: --header 'Name: value'. Credential and transport headers",
		"(Authorization, Cookie, Host, Content-Type, ...) are rejected;",
		"credentials come from the configured login instead.",
		"",
		"Credentials: the API's default when its root security is",
		"unambiguous, --auth <scheme> to pick one generated scheme (" + schemes + "),",
		"or --no-auth to send the request unauthenticated.",
		"--credentials @<file>|- or " + namedCredentialsEnv + " supplies exact scheme-keyed JSON;",
		"credential precedence is flags, environment, then saved credentials.",
		"",
		"--dry-run prints the resolved method, URL, headers, and body as JSON;",
		"credentials and sensitive headers are redacted, and no request is sent.",
		"UTF-8 bodies are strings; binary bodies use {encoding: base64, data: ...}.",
		"",
		"--out <path> atomically writes a successful response body to one",
		"file (an existing file needs --yes) and prints a JSON summary;",
		"stdout stays empty then. DELETE needs --yes, exactly like a",
		"destructive typed command. Exit 0 on success, 1 on an API,",
		"transport, or file failure, 2 on a usage error or refusal.",
	}, "\n")
}

