// rawAPIUsageCode classifies a local parse failure the way the typed
// command parser does.
func rawAPIUsageCode(err error) string {
	if err == nil {
		return "INVALID_USAGE"
	}
	if strings.Contains(err.Error(), "unknown flag") {
		return "UNKNOWN_FLAG"
	}
	if strings.Contains(err.Error(), "requires a value") {
		return "MISSING_ARGUMENT"
	}
	return "INVALID_USAGE"
}

// rawAPIHeaderDenied reports whether a caller header carries a credential
// or names a field the transport owns.
func rawAPIHeaderDenied(name string) bool {
	lower := strings.ToLower(strings.TrimSpace(name))
	for _, denied := range rawAPIDeniedHeaders {
		if lower == denied {
			return true
		}
	}
	return false
}

// rawAPIQueryDenied reports whether a query name is a credential
// destination this API owns.
func rawAPIQueryDenied(name string) bool {
	lower := strings.ToLower(name)
	for _, denied := range rawAPIDeniedQuery {
		if lower == denied {
			return true
		}
	}
	return false
}

// rawAPISchemeKnown reports whether --auth names a generated scheme.
func rawAPISchemeKnown(name string) bool {
	for _, scheme := range rawAuthSchemes {
		if scheme == name {
			return true
		}
	}
	return false
}

// validateRawAPIPath enforces the same single-leading-slash relative path
// the SDK's Raw capability requires, so unsafe paths fail as local usage
// errors with zero requests. The SDK re-checks on its side.
func validateRawAPIPath(path string) error {
	if len(path) == 0 || path[0] != '/' || (len(path) >= 2 && path[1] == '/') {
		return fmt.Errorf("PATH must be relative and begin with exactly one '/': %q", path)
	}
	if strings.ContainsAny(path, "?#") {
		return fmt.Errorf("PATH must not carry a query or fragment; pass query values with --query: %q", path)
	}
	if strings.ContainsRune(path, '\\') {
		return fmt.Errorf("PATH must not contain backslashes: %q", path)
	}
	lower := strings.ToLower(path)
	if strings.Contains(lower, "%2f") || strings.Contains(lower, "%5c") {
		return fmt.Errorf("PATH must not percent-encode path separators: %q", path)
	}
	if strings.Contains(lower, "%2e") {
		return fmt.Errorf("PATH must not percent-encode path dots: %q", path)
	}
	for _, r := range path {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("PATH must not contain control characters: %q", path)
		}
	}
	decoded := make([]byte, 0, len(path))
	for i := 0; i < len(path); i++ {
		if path[i] == '%' {
			if i+2 >= len(path) || !rawAPIIsHex(path[i+1]) || !rawAPIIsHex(path[i+2]) {
				return fmt.Errorf("PATH has an invalid %%-escape: %q", path)
			}
			decoded = append(decoded, rawAPIUnhex(path[i+1], path[i+2]))
			i += 2
			continue
		}
		decoded = append(decoded, path[i])
	}
	for _, r := range string(decoded) {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("PATH must not percent-encode control characters: %q", path)
		}
	}
	for _, segment := range strings.Split(string(decoded), "/") {
		if segment == "." || segment == ".." {
			return fmt.Errorf("PATH must not contain '.' or '..' segments: %q", path)
		}
	}
	return nil
}

// rawAPIIsHex reports whether c is an ASCII hexadecimal digit.
func rawAPIIsHex(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

// rawAPIUnhex decodes two ASCII hexadecimal digits into one byte.
func rawAPIUnhex(hi, lo byte) byte {
	var value byte
	switch {
	case hi >= '0' && hi <= '9':
		value = hi - '0'
	case hi >= 'a' && hi <= 'f':
		value = hi - 'a' + 10
	default:
		value = hi - 'A' + 10
	}
	value <<= 4
	switch {
	case lo >= '0' && lo <= '9':
		value += lo - '0'
	case lo >= 'a' && lo <= 'f':
		value += lo - 'a' + 10
	default:
		value += lo - 'A' + 10
	}
	return value
}

// rawAPIRefusal is a local --out refusal: the destination would not become
// a plain new file. It exits 2 without sending anything.
type rawAPIRefusal struct {
	code    string
	message string
	next    []string
}

// Error returns the refusal message, implementing error.
func (r *rawAPIRefusal) Error() string {
	return r.message
}

// rawAPICheckOut validates the --out destination before any request:
// symlinked paths are refused outright, and an existing file needs --yes.
func rawAPICheckOut(out string, confirmed bool) error {
	if out == "" {
		return nil
	}
	if err := mkdirAllNoSymlinks(filepath.Dir(out)); err != nil {
		return &rawAPIRefusal{code: "REFUSED", message: err.Error()}
	}
	if err := rejectSymlink(out); err != nil {
		return &rawAPIRefusal{code: "REFUSED", message: err.Error()}
	}
	info, err := os.Lstat(out)
	if err == nil {
		if info.IsDir() {
			return &rawAPIRefusal{code: "REFUSED", message: fmt.Sprintf("--out is a directory: %s", out)}
		}
		if !confirmed {
			return &rawAPIRefusal{
				code:    "CONFIRMATION_REQUIRED",
				message: fmt.Sprintf("the file already exists: %s", out),
				next:    []string{"rerun with --yes to overwrite it"},
			}
		}
	}
	return nil
}

// rawAPICheckOutDryRun validates existing path components without creating
// the destination directory or requiring confirmation for an overwrite.
func rawAPICheckOutDryRun(out string) error {
	if out == "" {
		return nil
	}
	abs, err := filepath.Abs(out)
	if err != nil {
		return err
	}
	volume := filepath.VolumeName(abs)
	current := volume + string(filepath.Separator)
	remaining := strings.TrimPrefix(filepath.Dir(abs), current)
	for _, part := range strings.Split(remaining, string(filepath.Separator)) {
		if part == "" || part == "." {
			continue
		}
		current = filepath.Join(current, part)
		info, statErr := os.Lstat(current)
		if os.IsNotExist(statErr) {
			return nil
		}
		if statErr != nil {
			return statErr
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return &rawAPIRefusal{code: "REFUSED", message: fmt.Sprintf("destination contains a symlink: %s", current)}
		}
		if !info.IsDir() {
			return &rawAPIRefusal{code: "REFUSED", message: fmt.Sprintf("destination component is not a directory: %s", current)}
		}
	}
	info, err := os.Lstat(abs)
	if err == nil {
		if info.Mode()&os.ModeSymlink != 0 {
			return &rawAPIRefusal{code: "REFUSED", message: fmt.Sprintf("destination is a symlink: %s", abs)}
		}
		if info.IsDir() {
			return &rawAPIRefusal{code: "REFUSED", message: fmt.Sprintf("--out is a directory: %s", out)}
		}
		return nil
	}
	if !os.IsNotExist(err) {
		return err
	}
	return nil
}

// rawAPIInstallFile atomically installs one regular file: the bytes land in
// a same-directory temporary first, then a rename replaces the
// destination. A failure never overwrites prior content and never leaves
// the temporary behind.
func rawAPIInstallFile(path string, body []byte) error {
	temp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	name := temp.Name()
	if _, err := temp.Write(body); err != nil {
		temp.Close()
		os.Remove(name)
		return err
	}
	if err := temp.Chmod(0644); err != nil {
		temp.Close()
		os.Remove(name)
		return err
	}
	if err := temp.Close(); err != nil {
		os.Remove(name)
		return err
	}
	return replaceFile(name, path)
}

// runRawAPICommand parses and executes `api METHOD PATH`: every check that
// can fail locally does, before any request is sent; the request itself
// goes through the SDK's Raw capability and nothing else.
func runRawAPICommand(ctx context.Context, args []string, stdout, stderr io.Writer) int {
	rest := args[1:]
	parsed, help, err := parseRawAPIArgs(rest)
	if help {
		fmt.Fprintln(stdout, rawAPIHelpText())
		return 0
	}
	if err != nil {
		return writeFailure(args, stdout, stderr, rawAPIUsageCode(err), err.Error(), nil, nil, 2)
	}
	// Auth flags share the typed commands' refusal of a missing,
	// flag-shaped, or empty value: `--base-url --debug` must fail as a
	// usage error rather than silently dropping the base URL.
	if err := validateAuthFlags(rest); err != nil {
		return writeFailure(args, stdout, stderr, rawAPIUsageCode(err), err.Error(), nil, nil, 2)
	}
	if !rawAPIMethods[parsed.method] {
		if parsed.method == "CONNECT" || parsed.method == "TRACE" {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", parsed.method+" is not available for raw requests", nil, nil, 2)
		}
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", fmt.Sprintf("unsupported method %s", parsed.method), nil, []string{"use GET, HEAD, POST, PUT, PATCH, DELETE, or OPTIONS"}, 2)
	}
	if parsed.body != nil && (parsed.method == "GET" || parsed.method == "HEAD") {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", "a request body is not allowed for GET or HEAD", nil, []string{"use POST, PUT, PATCH, or OPTIONS with --data, --raw, --file, or --stdin"}, 2)
	}
	if err := validateRawAPIPath(parsed.path); err != nil {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", err.Error(), nil, nil, 2)
	}
	for _, header := range parsed.headers {
		if rawAPIHeaderDenied(header.Name) {
			return writeFailure(args, stdout, stderr, "INVALID_USAGE", fmt.Sprintf("credential and transport headers cannot be set on a raw request: %s", header.Name), nil, []string{"credentials come from the configured login; use --auth or --no-auth"}, 2)
		}
	}
	if parsed.noAuth && parsed.authScheme != "" {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", "--no-auth and --auth are mutually exclusive", nil, nil, 2)
	}
	if parsed.authScheme != "" && !rawAPISchemeKnown(parsed.authScheme) {
		return writeFailure(args, stdout, stderr, "INVALID_USAGE", fmt.Sprintf("unknown auth scheme %q", parsed.authScheme), nil, []string{fmt.Sprintf("generated schemes: %s", strings.Join(rawAuthSchemes, ", "))}, 2)
	}
	if parsed.method == "DELETE" && !parsed.confirmed && !parsed.dryRun {
		return writeFailure(args, stdout, stderr, "CONFIRMATION_REQUIRED", "destructive operation requires --yes confirmation", nil, []string{fmt.Sprintf("rerun with '%s api delete %s --yes'", bin, parsed.path)}, 2)
	}
	if parsed.dryRun || parsed.out != "" {
		var outErr error
		if parsed.dryRun {
			outErr = rawAPICheckOutDryRun(parsed.out)
		} else {
			outErr = rawAPICheckOut(parsed.out, parsed.confirmed)
		}
		if outErr != nil {
			if refusal, ok := outErr.(*rawAPIRefusal); ok {
				return writeFailure(args, stdout, stderr, refusal.code, refusal.message, nil, refusal.next, 2)
			}
			return writeFailure(args, stdout, stderr, "REFUSED", outErr.Error(), nil, nil, 2)
		}
	}
	// --no-auth neither reads nor validates stored credentials, exactly
	// like an auth:none typed operation; the default and --auth keep the
	// documented precedence (flags, environment, stored).
	var op *opDef
	if parsed.noAuth {
		op = &opDef{Auth: "none"}
	}
	opts, optErr := authOptions(ctx, dryRunAuthArgs(args, parsed.dryRun), op, args)
	if optErr != nil {
		return writeAuthOptionsFailure(args, stdout, stderr, optErr)
	}
	var capture *dryRunTransport
	if parsed.dryRun {
		capture = &dryRunTransport{}
		opts = append(opts, dryRunClientOption(capture))
	}
	if !parsed.dryRun && (hasFlag(rest, "--debug") || os.Getenv(rawAPIDebugEnv) == "1") {
		opts = append(opts, sdk.WithDebug(func(event sdk.DebugEvent) {
			status := "error"
			if event.Status != 0 {
				status = fmt.Sprintf("%d", event.Status)
			}
			attempt := ""
			if event.Attempt > 1 {
				attempt = fmt.Sprintf(" attempt %d", event.Attempt)
			}
			requestID := ""
			if event.RequestID != "" {
				requestID = " " + event.RequestID
			}
			failure := ""
			if event.Err != nil {
				// Transport errors embed the full request URL, and an
				// apiKey-in-query spec bakes its credential into that URL;
				// the same redaction the error envelope applies — extended
				// to stored credential values and their URL-encoded forms
				// — keeps the debug line free of it.
				failure = ": " + redact(event.Err.Error(), args)
			}
			fmt.Fprintf(stderr, "%s %s %s -> %s (%dms)%s%s%s\n", bin, event.Method, event.Path, status, event.DurationMS, attempt, requestID, failure)
		}))
	}
	client, err := sdk.New(opts...)
	if err != nil {
		return writeFailure(args, stdout, stderr, failureCode(err), "unable to initialize the client", errorDetail(err, args), nil, 1)
	}
	rawReq := sdk.RawRequest{
		Method:      parsed.method,
		Path:        parsed.path,
		Query:       parsed.query,
		Headers:     parsed.headers,
		Body:        parsed.body,
		ContentType: parsed.contentType,
	}
	if parsed.noAuth {
		rawReq.Auth = &sdk.RawAuth{None: true}
	} else if parsed.authScheme != "" {
		rawReq.Auth = &sdk.RawAuth{Scheme: parsed.authScheme}
	}
	resp, err := client.Raw(ctx, rawReq)
	if parsed.dryRun && capture.request != nil {
		return writeDryRunPreview(args, capture, stdout, stderr)
	}
	if err != nil {
		if ctx.Err() != nil {
			return 130
		}
		code := failureCode(err)
		if code == "AUTH_INVALID" && !credentialPresent(args) {
			code = "NO_AUTH"
		}
		message, next, retryable := failureGuidance(err, code)
		return writeFailureEnvelope(args, stdout, stderr, code, message, errorDetail(err, args), next, &retryable, 1)
	}
	if parsed.out != "" {
		if err := rawAPIInstallFile(parsed.out, resp.Body); err != nil {
			return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not write the response file", err.Error(), nil, 1)
		}
		summary := struct {
			Ok        bool   `json:"ok"`
			Path      string `json:"path"`
			Bytes     int    `json:"bytes"`
			Status    int    `json:"status"`
			RequestID string `json:"request_id,omitempty"`
		}{Ok: true, Path: parsed.out, Bytes: len(resp.Body), Status: resp.StatusCode, RequestID: resp.RequestID}
		encoded, marshalErr := json.Marshal(summary)
		if marshalErr != nil {
			return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not encode the file summary", marshalErr.Error(), nil, 1)
		}
		fmt.Fprintln(stdout, string(encoded))
		return 0
	}
	if _, err := stdout.Write(resp.Body); err != nil {
		return writeFailure(args, stdout, stderr, "CALL_FAILED", "could not write the response", err.Error(), nil, 1)
	}
	return 0
}
